import { Type } from 'class-transformer';
import { IsIn, IsInt, IsNumber, IsOptional, IsString, IsUUID, Length, Max, Min } from 'class-validator';

export class WalletAdjustDto {
  @IsIn(['credit', 'debit'])
  direction!: 'credit' | 'debit';

  @Type(() => Number)
  @IsNumber({ maxDecimalPlaces: 2 })
  @Min(0.01)
  @Max(100_000)
  amount!: number;

  /** Shown in the ledger and the audit log. */
  @IsString()
  @Length(5, 160)
  reason!: string;

  /** Generated by the client per submission; a retry with the same key is a no-op. */
  @IsUUID()
  idempotencyKey!: string;
}

export class LedgerQueryDto {
  @IsOptional() @Type(() => Number) @IsInt() @Min(1) page?: number;
  @IsOptional() @Type(() => Number) @IsInt() @Min(1) @Max(100) limit?: number;
  @IsOptional() @IsString() @Length(1, 32) type?: string;
  @IsOptional() @IsString() @Length(1, 32) username?: string;
}

export class OverviewQueryDto {
  @IsOptional() @Type(() => Number) @IsIn([1, 7, 30, 90]) days?: number;
}

export class AgentPlayersQueryDto {
  @IsOptional() @Type(() => Number) @IsInt() @Min(1) page?: number;
  @IsOptional() @Type(() => Number) @IsInt() @Min(1) @Max(50) limit?: number;
  @IsOptional() @IsString() @Length(1, 32) search?: string;
}

export class AgentReportQueryDto {
  @IsOptional() @Type(() => Number) @IsIn([7, 30, 90]) days?: number;
}

export class AssignPlayerDto {
  @IsString()
  @Length(3, 32)
  username!: string;
}
